def step_6(input_list):
    """
    Step 6: Eval risk combination

    - Input: input_list (expected: list of booleans, one per event from prior step; e.g. length 12)
    - Output: List[int] of combined_risk_score values (0-100) aligned with input_list order.
              For indices where input_list[i] is False or where evaluation cannot be performed,
              the function returns 0 (safe default).
    - Purpose:
        * For each eligible event (input_list[i] is True), coalesce and clamp the event's
          risk_score to the range [0,100]. If the event is a 'local' event, the local
          normalized risk is used; if it's a 'brain' event, the brain normalized risk is used.
        * To produce a combined risk for an event, find other events that belong to the same
          identity group (host preferred, otherwise db_name+target_account), gather the
          maximum normalized_local_risk and normalized_brain_risk for that group, then take
          combined_risk_score = max(normalized_local_risk, normalized_brain_risk).
        * This function returns the numeric combined score for each index so downstream
          steps can make numeric comparisons/thresholding.

    Notes:
    - The function expects the corresponding event dict list produced earlier (e.g. step_2 output)
      to be available in module globals() under a common name such as:
        "step_2_output", "step2_output", "processed_entries_step_2", "records", "step_2_data", "step_2"
      If no usable records list is found, the function returns a list of zeros (safe default).
    - Robust to malformed risk_score values, missing fields, and non-dict records.
    """

    # Defensive: input_list must be a list
    if not isinstance(input_list, list):
        return []

    num = len(input_list)

    # Attempt to locate the corresponding list of event dicts from globals()
    records = None
    g = globals()
    possible_names = (
        "step_2_output", "step2_output", "processed_entries_step_2",
        "records", "step_2_data", "step_2", "step2"
    )
    for name in possible_names:
        cand = g.get(name)
        if isinstance(cand, list) and len(cand) >= num and all(isinstance(x, dict) for x in cand[:num]):
            records = cand
            break

    # If we cannot find a usable records list, return safe default zeros
    if records is None:
        return [0] * num

    # Helper: coerce risk_score to int and clamp to 0-100
    def normalize_risk(val):
        try:
            if val is None:
                v = 0.0
            elif isinstance(val, (int, float)):
                v = float(val)
            elif isinstance(val, str):
                # try to parse numeric string
                v = float(val.strip())
            else:
                # unknown type -> fallback 0
                v = 0.0
        except Exception:
            v = 0.0
        # clamp to 0-100
        v = max(0.0, min(100.0, v))
        # return integer risk for consistency
        return int(round(v))

    # Helper: determine match key (host preferred, else (db_name, target_account))
    def match_key(entry):
        try:
            host = entry.get("host")
            if isinstance(host, str) and host.strip() != "":
                return ("host", host.strip().lower())
            db = entry.get("db_name")
            ta = entry.get("target_account")
            if isinstance(db, str) and db.strip() != "" and isinstance(ta, str) and ta.strip() != "":
                return ("db_target", (db.strip().lower(), ta.strip().lower()))
        except Exception:
            pass
        return (None, None)

    # Helpers: classify brain vs local
    def is_brain_event(entry):
        try:
            d = entry.get("detector")
            return isinstance(d, str) and d.strip().upper() in {"BRAIN", "BRAIN_MSSQL"}
        except Exception:
            return False

    def is_local_event(entry):
        try:
            detected_by = entry.get("detected_by")
            detector = entry.get("detector")
            if isinstance(detected_by, str) and detected_by.strip().upper() == "LOCAL":
                return True
            if isinstance(detector, str) and detector.strip().upper() == "LOCAL":
                return True
            return False
        except Exception:
            return False

    # Precompute normalized risk and match key for each record (only for the first num entries)
    pre = []
    for i in range(num):
        rec = records[i] if i < len(records) and isinstance(records[i], dict) else {}
        try:
            key = match_key(rec)
            brain_flag = is_brain_event(rec)
            local_flag = is_local_event(rec)
            risk_raw = rec.get("risk_score")
            norm_risk = normalize_risk(risk_raw)
        except Exception:
            key = (None, None)
            brain_flag = False
            local_flag = False
            norm_risk = 0
        pre.append({
            "match_key": key,
            "is_brain": brain_flag,
            "is_local": local_flag,
            "norm_risk": norm_risk
        })

    # Aggregate per match_key: compute max brain risk and max local risk in each group
    group_scores = {}  # map match_key -> {"max_brain": int, "max_local": int}
    for i in range(num):
        mk = pre[i]["match_key"]
        # Use the raw tuple as dict key (it is hashable)
        if mk not in group_scores:
            group_scores[mk] = {"max_brain": 0, "max_local": 0}
        if pre[i]["is_brain"]:
            # update max brain risk
            if pre[i]["norm_risk"] > group_scores[mk]["max_brain"]:
                group_scores[mk]["max_brain"] = pre[i]["norm_risk"]
        if pre[i]["is_local"]:
            # update max local risk
            if pre[i]["norm_risk"] > group_scores[mk]["max_local"]:
                group_scores[mk]["max_local"] = pre[i]["norm_risk"]

    # Build result: for each index i where input_list[i] is True, compute combined risk:
    # combined_risk_score = max(normalized_local_risk, normalized_brain_risk) for the event's group
    results = [0] * num
    try:
        for i in range(num):
            try:
                eligible = bool(input_list[i])
            except Exception:
                eligible = False

            if not eligible:
                # not eligible per previous step -> combined risk 0
                results[i] = 0
                continue

            mk = pre[i]["match_key"]
            if mk not in group_scores:
                # no group information -> use this event's own normalized risk
                results[i] = pre[i]["norm_risk"]
                continue

            g = group_scores[mk]
            combined = max(g.get("max_local", 0), g.get("max_brain", 0))
            # ensure final clamp as well (should already be 0-100)
            combined = max(0, min(100, int(round(combined))))
            results[i] = combined
    except Exception:
        # On any unexpected error, return conservative zeros
        return [0] * num

    return results

def step_8(input_list):
    """
    Step 8: Build compact raw message summaries for events.

    - Input: input_list (expected: list of booleans, one per event; e.g. length 12)
    - Output: returns a list of booleans (same as input_list) so the pipeline can continue.
      Side-effect: if a companion records list from prior steps is available in globals()
      (common names checked), this function will annotate each record dict with:
        - 'raw_summary' : { sha256, snippet, length, truncated }
      and, when a correlated counterpart (opposite role) is found in the same identity group,
      it will also add:
        - 'local_raw_summary' : {...}
        - 'brain_raw_summary' : {...}
      These annotations use precomputed fields if present (raw_sha256, raw_snippet,
      raw_length, raw_truncated); otherwise they are computed here.

    Notes:
    - Defensive: if input_list is not a list, returns [].
    - Does not modify input_list items; returns a shallow copy of the boolean list.
    - Works even when many entries are False (no-op beyond per-record summary).
    """
    import hashlib

    # Defensive input check
    if not isinstance(input_list, list):
        return []

    # Attempt to locate the corresponding event records list from globals.
    # Common names used earlier in pipeline:
    possible_names = (
        "step_2_output", "step2_output", "processed_entries_step_2",
        "records", "step_2_data", "step_2"
    )
    g = globals()
    records = None
    for name in possible_names:
        cand = g.get(name)
        if isinstance(cand, list) and len(cand) >= len(input_list) and all(isinstance(x, dict) for x in cand[:len(input_list)]):
            records = cand
            break

    # If no records available, nothing to annotate; return a shallow copy of input_list.
    if records is None:
        return list(input_list)

    # Helper: coalesce-like function
    def coalesce(value, default):
        return value if (value is not None) else default

    # Helper: compute sha256 hex digest for a text (safe for non-str by coercing to str)
    def compute_sha256(text):
        try:
            if not isinstance(text, (bytes, str)):
                text = str(text)
            if isinstance(text, str):
                b = text.encode("utf-8", errors="replace")
            else:
                b = text
            return hashlib.sha256(b).hexdigest()
        except Exception:
            # On any error, return empty string as safe fallback
            return ""

    # Helper: coerce length to int if possible
    def coerce_length(val):
        try:
            if val is None:
                return None
            if isinstance(val, int):
                return val
            if isinstance(val, float):
                return int(round(val))
            if isinstance(val, str):
                s = val.strip()
                if s == "":
                    return None
                return int(float(s))
            return None
        except Exception:
            return None

    # Helper: coerce truncated to bool if possible
    def coerce_truncated(val):
        try:
            if isinstance(val, bool):
                return val
            if isinstance(val, (int, float)):
                return bool(val)
            if isinstance(val, str):
                s = val.strip().lower()
                if s in ("true", "1", "yes", "y"):
                    return True
                if s in ("false", "0", "no", "n"):
                    return False
            return None
        except Exception:
            return None

    # Helper: generate a match key for grouping/pairing (host preferred, else db_name+target_account)
    def match_key_for_pairing(entry):
        try:
            host = entry.get("host")
            if isinstance(host, str) and host.strip() != "":
                return ("host", host.strip().lower())
            db = entry.get("db_name")
            ta = entry.get("target_account")
            if isinstance(db, str) and db.strip() != "" and isinstance(ta, str) and ta.strip() != "":
                return ("db_target", (db.strip().lower(), ta.strip().lower()))
        except Exception:
            pass
        return (None, None)

    # Helper: classify roles for pairing
    def is_brain(entry):
        try:
            d = entry.get("detector")
            return isinstance(d, str) and d.strip().upper() in {"BRAIN", "BRAIN_MSSQL"}
        except Exception:
            return False

    def is_local(entry):
        try:
            detected_by = entry.get("detected_by")
            detector = entry.get("detector")
            if isinstance(detected_by, str) and detected_by.strip().upper() == "LOCAL":
                return True
            if isinstance(detector, str) and detector.strip().upper() == "LOCAL":
                return True
            return False
        except Exception:
            return False

    num = len(input_list)
    # Precompute per-record summaries and pairing keys
    summaries = [None] * num
    keys = [ (None, None) ] * num
    roles = [ {"is_brain": False, "is_local": False} for _ in range(num) ]

    for i in range(num):
        try:
            rec = records[i]
            if not isinstance(rec, dict):
                summaries[i] = {
                    "sha256": "",
                    "snippet": "",
                    "length": 0,
                    "truncated": False
                }
                keys[i] = (None, None)
                continue

            # Raw message (coalesce to "")
            raw = coalesce(rec.get("raw_message"), "")
            if not isinstance(raw, str):
                try:
                    raw = str(raw)
                except Exception:
                    raw = ""

            # Precomputed values if present
            pre_sha = rec.get("raw_sha256")
            pre_snip = rec.get("raw_snippet")
            pre_len = rec.get("raw_length")
            pre_trunc = rec.get("raw_truncated")

            # Compute length
            length_val = coerce_length(pre_len)
            if length_val is None:
                length_val = len(raw)

            # Compute truncated flag
            truncated_val = coerce_truncated(pre_trunc)
            if truncated_val is None:
                truncated_val = (length_val > 512)

            # Compute snippet
            if isinstance(pre_snip, str) and pre_snip.strip() != "":
                snippet_val = pre_snip
            else:
                # substr(raw, 0, 512)
                snippet_val = raw[:512]

            # Compute sha256
            if isinstance(pre_sha, str) and pre_sha.strip() != "":
                sha_val = pre_sha.strip()
            else:
                sha_val = compute_sha256(raw)

            summary = {
                "sha256": sha_val,
                "snippet": snippet_val,
                "length": length_val,
                "truncated": bool(truncated_val)
            }

            summaries[i] = summary
            keys[i] = match_key_for_pairing(rec)
            roles[i]["is_brain"] = is_brain(rec)
            roles[i]["is_local"] = is_local(rec)

            # Attach per-record summary as 'raw_summary' for downstream use
            try:
                rec["raw_summary"] = summary
            except Exception:
                # If we cannot write into the record, silently skip attachment
                pass

        except Exception:
            # On unexpected error, set a safe empty summary
            summaries[i] = {
                "sha256": "",
                "snippet": "",
                "length": 0,
                "truncated": False
            }
            keys[i] = (None, None)
            roles[i]["is_brain"] = False
            roles[i]["is_local"] = False

    # Attempt to pair opposite-role events within the same identity group (host or db_target)
    # For each index i that is marked True in input_list, find any j != i such that:
    #  - input_list[j] is True
    #  - roles are opposite (one brain, one local)
    #  - keys[i] == keys[j] and key method is not None
    # If such a counterpart exists, annotate both records with 'local_raw_summary' and 'brain_raw_summary'.
    for i in range(num):
        try:
            if not input_list[i]:
                continue
            key_i = keys[i]
            if key_i[0] is None:
                continue  # cannot match without a usable key
            # Look for counterpart
            for j in range(num):
                if j == i:
                    continue
                if not input_list[j]:
                    continue
                key_j = keys[j]
                if key_j != key_i:
                    continue
                # require opposite roles
                if not ((roles[i]["is_brain"] and roles[j]["is_local"]) or (roles[i]["is_local"] and roles[j]["is_brain"])):
                    continue
                # We found a counterpart; identify which is brain/local
                if roles[i]["is_brain"]:
                    brain_idx, local_idx = i, j
                else:
                    brain_idx, local_idx = j, i

                # Attach summaries to records (if writable)
                try:
                    rec_b = records[brain_idx]
                    rec_l = records[local_idx]
                    # Use existing per-record summaries or fallback to summaries array
                    brain_summary = summaries[brain_idx] if summaries[brain_idx] is not None else {"sha256":"", "snippet":"", "length":0, "truncated":False}
                    local_summary = summaries[local_idx] if summaries[local_idx] is not None else {"sha256":"", "snippet":"", "length":0, "truncated":False}
                    if isinstance(rec_b, dict):
                        rec_b["brain_raw_summary"] = brain_summary
                        rec_b["local_raw_summary"] = local_summary
                    if isinstance(rec_l, dict):
                        rec_l["brain_raw_summary"] = brain_summary
                        rec_l["local_raw_summary"] = local_summary
                except Exception:
                    # Non-fatal: if any assignment fails, continue
                    pass

                # If multiple counterparts exist, we only need to annotate once; continue searching
        except Exception:
            # Ignore per-index errors and continue
            continue

    # Return a shallow copy of the boolean list so downstream steps receive the same eligibility array.
    return list(input_list)

def step_9(input_list):
    """
    Step 9: Normalize and deduplicate detector and rule_name display values for alert payload.

    - Input: input_list (expected: list of booleans, one per event)
    - Output: list of booleans (same as input_list) so pipeline continuity is preserved.
      Side-effect: annotate corresponding event dicts (if available in globals) with:
        - 'detectors_normalized': list of distinct normalized detector display values (lowercase)
        - 'rule_names_normalized': list of distinct normalized rule_name display values (lowercase)

    Normalization rules (per item / per correlated pair):
    - detector_local_norm_lc = coalesce(local_event.detector_normalized,
                                        trim(lower(coalesce(local_event.detector_local_norm, ""))))
    - detector_brain_norm_lc = coalesce(brain_event.detector_normalized,
                                        trim(lower(coalesce(brain_event.detector_brain_norm, ""))))
      Then detectors_normalized = distinct([detector_local_norm_lc, detector_brain_norm_lc])
    - rule_name_local_norm_lc = coalesce(local_event.rule_name_normalized,
                                         trim(lower(coalesce(local_event.rule_name, ""))))
    - rule_name_brain_norm_lc = coalesce(brain_event.rule_name_normalized,
                                         trim(lower(coalesce(brain_event.rule_name, ""))))
      Then rule_names_normalized = distinct([rule_name_local_norm_lc, rule_name_brain_norm_lc])

    The function is defensive and will return a shallow copy of input_list in all error cases.
    """
    # Defensive: input_list must be a list
    if not isinstance(input_list, list):
        return []

    # Try to locate the companion event records list from globals() (common names used earlier)
    g = globals()
    possible_names = (
        "step_2_output", "step2_output", "processed_entries_step_2",
        "records", "step_2_data", "step_2"
    )
    records = None
    for name in possible_names:
        cand = g.get(name)
        if isinstance(cand, list) and len(cand) >= len(input_list) and all(isinstance(x, dict) for x in cand[:len(input_list)]):
            records = cand
            break

    # If no records available, nothing to annotate; return a shallow copy of input_list.
    if records is None:
        return list(input_list)

    num = len(input_list)
    # Helper: safe trim/lower utility; returns None for empty/None
    def _trim_lower(val):
        try:
            if not isinstance(val, str):
                return None
            s = val.strip()
            if s == "":
                return None
            return s.lower()
        except Exception:
            return None

    # Helper: coalesce reading multiple keys from an entry (in order)
    def _first_non_empty(entry, *keys):
        for k in keys:
            try:
                v = entry.get(k)
            except Exception:
                v = None
            if isinstance(v, str) and v.strip() != "":
                return v
        return None

    # Match key (host preferred, else db_name+target_account) - same logic used earlier
    def _match_key(entry):
        try:
            host = entry.get("host")
            if isinstance(host, str) and host.strip() != "":
                return ("host", host.strip().lower())
            db = entry.get("db_name")
            ta = entry.get("target_account")
            if isinstance(db, str) and db.strip() != "" and isinstance(ta, str) and ta.strip() != "":
                return ("db_target", (db.strip().lower(), ta.strip().lower()))
        except Exception:
            pass
        return (None, None)

    # Role classification helpers
    def _is_brain(entry):
        try:
            d = entry.get("detector")
            return isinstance(d, str) and d.strip().upper() in {"BRAIN", "BRAIN_MSSQL"}
        except Exception:
            return False

    def _is_local(entry):
        try:
            detected_by = entry.get("detected_by")
            detector = entry.get("detector")
            if isinstance(detected_by, str) and detected_by.strip().upper() == "LOCAL":
                return True
            if isinstance(detector, str) and detector.strip().upper() == "LOCAL":
                return True
            return False
        except Exception:
            return False

    # Precompute keys and roles for first num records (safe defaults if malformed)
    keys = [ (None, None) ] * num
    roles = [ {"is_brain": False, "is_local": False} for _ in range(num) ]
    for i in range(num):
        rec = records[i] if i < len(records) and isinstance(records[i], dict) else {}
        try:
            keys[i] = _match_key(rec)
            roles[i]["is_brain"] = _is_brain(rec)
            roles[i]["is_local"] = _is_local(rec)
        except Exception:
            keys[i] = (None, None)
            roles[i]["is_brain"] = False
            roles[i]["is_local"] = False

    # Helper to build normalized detector string for a given entry and role-type (local vs brain)
    def _detector_norm_for_local(entry):
        # Per spec: prefer entry.detector_normalized -> lower(coalesce(detector_local_norm, ""))
        # Check 'detector_normalized' first, then 'detector_local_norm' (and fallback to detector)
        val = _first_non_empty(entry, "detector_normalized")
        if isinstance(val, str) and val.strip() != "":
            return _trim_lower(val)
        # fallback to detector_local_norm field (may have been set earlier)
        val2 = _first_non_empty(entry, "detector_local_norm", "detector")
        return _trim_lower(val2)

    def _detector_norm_for_brain(entry):
        # Per spec: prefer entry.detector_normalized -> lower(coalesce(detector_brain_norm, ""))
        val = _first_non_empty(entry, "detector_normalized")
        if isinstance(val, str) and val.strip() != "":
            return _trim_lower(val)
        val2 = _first_non_empty(entry, "detector_brain_norm", "detector")
        return _trim_lower(val2)

    # Helper to build normalized rule_name for a given entry and role-type (local vs brain)
    def _rule_name_norm_for_local(entry):
        # prefer entry.rule_name_normalized or entry.rule_name_normalized_for_matching, else lower(rule_name)
        val = _first_non_empty(entry, "rule_name_normalized", "rule_name_normalized_for_matching")
        if isinstance(val, str) and val.strip() != "":
            return _trim_lower(val)
        return _trim_lower(_first_non_empty(entry, "rule_name"))

    def _rule_name_norm_for_brain(entry):
        val = _first_non_empty(entry, "rule_name_normalized", "rule_name_normalized_for_matching")
        if isinstance(val, str) and val.strip() != "":
            return _trim_lower(val)
        return _trim_lower(_first_non_empty(entry, "rule_name"))

    # Distinct-preserving order function for small lists
    def _distinct_preserve(items):
        seen = set()
        out = []
        for item in items:
            if item is None:
                continue
            if item in seen:
                continue
            seen.add(item)
            out.append(item)
        return out

    # Iterate over each entry and compute normalized/deduped lists using counterparts where possible
    for i in range(num):
        try:
            # Default: no annotation if record not a dict
            if i >= len(records) or not isinstance(records[i], dict):
                continue

            # Only compute/annotate for items that are eligible per input_list (keep conservative behavior)
            try:
                eligible = bool(input_list[i])
            except Exception:
                eligible = False

            # We'll still compute normalized values even if not eligible so payload is complete, but follow pipeline semantics:
            # if not eligible we will annotate with single-entry normalization for the event itself.
            rec_i = records[i]

            # Find counterparts j that are eligible and have same match key and opposite role
            counterparts = []
            key_i = keys[i]
            if key_i[0] is not None:
                for j in range(num):
                    if j == i:
                        continue
                    if not (j < len(records) and isinstance(records[j], dict)):
                        continue
                    try:
                        if not bool(input_list[j]):
                            continue
                    except Exception:
                        continue
                    # require same key
                    if keys[j] != key_i:
                        continue
                    # require opposite role: one brain and one local
                    if not ((roles[i]["is_brain"] and roles[j]["is_local"]) or (roles[i]["is_local"] and roles[j]["is_brain"])):
                        continue
                    counterparts.append(j)

            detectors_vals = []
            rule_names_vals = []

            # If we found counterparts, aggregate normalized values from all pair partners
            if counterparts:
                # For each counterpart, determine which is local and which is brain and collect normalized values
                for j in counterparts:
                    rec_j = records[j]
                    # Determine local_event and brain_event between rec_i and rec_j
                    if roles[i]["is_local"] and roles[j]["is_brain"]:
                        local_rec, brain_rec = rec_i, rec_j
                    elif roles[i]["is_brain"] and roles[j]["is_local"]:
                        local_rec, brain_rec = rec_j, rec_i
                    else:
                        # fallback: if roles ambiguous, try to assign based on actual fields per entry
                        if roles[i]["is_local"]:
                            local_rec, brain_rec = rec_i, rec_j
                        elif roles[i]["is_brain"]:
                            local_rec, brain_rec = rec_j, rec_i
                        else:
                            local_rec, brain_rec = rec_i, rec_j

                    d_local = _detector_norm_for_local(local_rec)
                    d_brain = _detector_norm_for_brain(brain_rec)
                    detectors_vals.extend([d_local, d_brain])

                    rn_local = _rule_name_norm_for_local(local_rec)
                    rn_brain = _rule_name_norm_for_brain(brain_rec)
                    rule_names_vals.extend([rn_local, rn_brain])
            else:
                # No counterpart found: normalize using the event itself for both roles (best-effort)
                d_local = _detector_norm_for_local(rec_i)
                d_brain = _detector_norm_for_brain(rec_i)
                detectors_vals.extend([d_local, d_brain])

                rn_local = _rule_name_norm_for_local(rec_i)
                rn_brain = _rule_name_norm_for_brain(rec_i)
                rule_names_vals.extend([rn_local, rn_brain])

            # Build distinct lists preserving order and dropping None/empty
            detectors_normalized = _distinct_preserve([v for v in (detectors_vals or []) if isinstance(v, str) and v.strip() != ""])
            rule_names_normalized = _distinct_preserve([v for v in (rule_names_vals or []) if isinstance(v, str) and v.strip() != ""])

            # Annotate the record with normalized lists (use safe assignment)
            try:
                rec_i["detectors_normalized"] = detectors_normalized
                rec_i["rule_names_normalized"] = rule_names_normalized
            except Exception:
                # If assignment fails, continue without raising to keep pipeline robust
                pass

        except Exception:
            # For robustness, skip problematic index rather than aborting entire run
            continue

    # Return a shallow copy of the boolean list so downstream steps receive the same eligibility array.
    return list(input_list)

def step_10(input_list):
    """
    Step 10: Assemble alert payloads for correlated LOCAL <-> BRAIN event pairs.

    - Input: input_list (expected: list of booleans, one per event; e.g. length 12)
    - Output: list of booleans (same length as input_list). For each index i:
        * True  -> an alert payload was successfully assembled for the event at index i
                  (i participated in a correlated pair and required fields were present).
        * False -> no payload assembled for that event (not eligible, missing counterpart,
                  or missing required fields).
    - Side effects:
        * If a companion records list (events) is available in globals() under common names
          (e.g. "step_2_output", "records", "step2_output", ...), this function will:
            - attach an "alert_payload" dict to each record dict that successfully produced a payload,
            - create/append payload dicts into a global list named "assembled_alerts" (created if missing).
    - Alert payload structure:
        alert_payload = {
            "alert_name": <coalesced meta.alert_name or event.alert_name>,
            "detection_source": <coalesce(meta.detection_source, meta.source) or event.source fields>,
            "severity": <coalesced severity_mapped>,
            "correlation_window": "15m",
            "timestamp_local": local_event._time,
            "timestamp_brain": brain_event._time,
            "host": local_event.host,
            "db_name": local_event.db_name,
            "target_account": local_event.target_account,
            "user": coalesce(local_event.user, brain_event.user),
            "action": coalesce(local_event.action, brain_event.action),
            "detectors": detectors_normalized,          # list
            "rule_names": rule_names_normalized,        # list
            "risk_score": combined_risk_score,          # int
            "raw_messages": [
                {"source": "local", "summary": local_raw_summary},
                {"source": "brain", "summary": brain_raw_summary}
            ]
        }
    - Robust to missing/ malformed fields; will only mark an index True if the payload could be meaningfully assembled.
    """
    from copy import deepcopy

    # Defensive input validation: must be a list
    if not isinstance(input_list, list):
        return []

    num = len(input_list)
    results = [False] * num  # default: no payload assembled

    # Try to locate companion records list in globals()
    g = globals()
    candidate_names = (
        "step_2_output", "step2_output", "processed_entries_step_2",
        "records", "step_2_data", "step_2"
    )
    records = None
    for name in candidate_names:
        cand = g.get(name)
        if isinstance(cand, list) and len(cand) >= num and all(isinstance(x, dict) for x in cand[:num]):
            records = cand
            break

    # If no records available, nothing to assemble; return shallow copy of input_list as booleans (all False likely)
    if records is None:
        return list(input_list)

    # Try to find meta object in globals (optional)
    meta = g.get("meta") if isinstance(g.get("meta"), dict) else None

    # Helper coalesce utility
    def coalesce(*vals):
        for v in vals:
            if v is None:
                continue
            # treat empty string as missing
            if isinstance(v, str) and v.strip() == "":
                continue
            return v
        return None

    # Helper to determine match key (host preferred, else db_name+target_account)
    def match_key(entry):
        try:
            host = entry.get("host")
            if isinstance(host, str) and host.strip() != "":
                return ("host", host.strip().lower())
            db = entry.get("db_name")
            ta = entry.get("target_account")
            if isinstance(db, str) and db.strip() != "" and isinstance(ta, str) and ta.strip() != "":
                return ("db_target", (db.strip().lower(), ta.strip().lower()))
        except Exception:
            pass
        return (None, None)

    # Helper role classification
    def is_brain(entry):
        try:
            d = entry.get("detector")
            return isinstance(d, str) and d.strip().upper() in {"BRAIN", "BRAIN_MSSQL"}
        except Exception:
            return False

    def is_local(entry):
        try:
            detected_by = entry.get("detected_by")
            detector = entry.get("detector")
            if isinstance(detected_by, str) and detected_by.strip().upper() == "LOCAL":
                return True
            if isinstance(detector, str) and detector.strip().upper() == "LOCAL":
                return True
            return False
        except Exception:
            return False

    # Helper: ensure value is a list of strings (normalize)
    def ensure_str_list(v):
        if v is None:
            return []
        if isinstance(v, list):
            out = []
            for it in v:
                if isinstance(it, str) and it.strip() != "":
                    out.append(it.strip())
            return out
        if isinstance(v, str):
            s = v.strip()
            return [s] if s != "" else []
        return []

    # Ensure global assembled_alerts exists (list)
    assembled_alerts = g.get("assembled_alerts")
    if not isinstance(assembled_alerts, list):
        assembled_alerts = []
        # Try to set into globals for downstream visibility
        try:
            g["assembled_alerts"] = assembled_alerts
        except Exception:
            # if cannot set, just keep local list

            pass

    # Precompute keys and roles for each record
    keys = [ (None, None) ] * num
    roles = [ {"is_brain": False, "is_local": False} for _ in range(num) ]
    for i in range(num):
        rec = records[i] if i < len(records) and isinstance(records[i], dict) else {}
        try:
            keys[i] = match_key(rec)
            roles[i]["is_brain"] = is_brain(rec)
            roles[i]["is_local"] = is_local(rec)
        except Exception:
            keys[i] = (None, None)
            roles[i]["is_brain"] = False
            roles[i]["is_local"] = False

    # For each index eligible per input_list, attempt to find a counterpart and assemble payload
    for i in range(num):
        try:
            # Only attempt if eligible per input_list
            try:
                eligible = bool(input_list[i])
            except Exception:
                eligible = False
            if not eligible:
                continue

            rec_i = records[i]
            if not isinstance(rec_i, dict):
                continue

            # Must have a usable match key
            key_i = keys[i]
            if key_i[0] is None:
                continue

            # Find counterpart j != i with same key, eligible and opposite role
            counterpart_idx = None
            for j in range(num):
                if j == i:
                    continue
                if not (j < len(records) and isinstance(records[j], dict)):
                    continue
                try:
                    if not bool(input_list[j]):
                        continue
                except Exception:
                    continue
                if keys[j] != key_i:
                    continue
                # roles must be opposite (one brain, one local)
                if (roles[i]["is_brain"] and roles[j]["is_local"]) or (roles[i]["is_local"] and roles[j]["is_brain"]):
                    counterpart_idx = j
                    break

            if counterpart_idx is None:
                # no counterpart found -> cannot assemble pair payload
                continue

            rec_j = records[counterpart_idx]

            # Identify local_event and brain_event explicitly
            if roles[i]["is_local"] and roles[counterpart_idx]["is_brain"]:
                local_event = rec_i
                brain_event = rec_j
                local_idx = i
                brain_idx = counterpart_idx
            elif roles[i]["is_brain"] and roles[counterpart_idx]["is_local"]:
                local_event = rec_j
                brain_event = rec_i
                local_idx = counterpart_idx
                brain_idx = i
            else:
                # Unexpected role combo; skip
                continue

            # Gather payload fields with coalescing and safe access
            alert_name = coalesce(
                (meta.get("alert_name") if isinstance(meta, dict) else None),
                rec_i.get("alert_name"),
                local_event.get("alert_name"),
                brain_event.get("alert_name")
            )

            detection_source = coalesce(
                (meta.get("detection_source") if isinstance(meta, dict) else None),
                (meta.get("source") if isinstance(meta, dict) else None),
                rec_i.get("detection_source"),
                rec_i.get("source"),
                local_event.get("detection_source"),
                local_event.get("source"),
                brain_event.get("detection_source"),
                brain_event.get("source")
            )

            # severity: prefer annotated per-record severity_mapped, then meta, else None
            severity = coalesce(
                local_event.get("severity_mapped"),
                brain_event.get("severity_mapped"),
                (meta.get("severity") if isinstance(meta, dict) else None),
                rec_i.get("severity_mapped")
            )

            timestamp_local = local_event.get("_time")
            timestamp_brain = brain_event.get("_time")

            host = local_event.get("host")
            db_name = local_event.get("db_name")
            target_account = local_event.get("target_account")

            user_field = coalesce(local_event.get("user"), brain_event.get("user"))
            action_field = coalesce(local_event.get("action"), brain_event.get("action"))

            # detectors_normalized and rule_names_normalized: prefer local_event fields, else brain_event, else combine
            detectors_local = ensure_str_list(local_event.get("detectors_normalized") or local_event.get("detectors_normalized"))
            detectors_brain = ensure_str_list(brain_event.get("detectors_normalized") or brain_event.get("detectors_normalized"))
            detectors_combined = []
            for d in (detectors_local + detectors_brain):
                if d not in detectors_combined:
                    detectors_combined.append(d)

            rule_names_local = ensure_str_list(local_event.get("rule_names_normalized") or local_event.get("rule_names_normalized"))
            rule_names_brain = ensure_str_list(brain_event.get("rule_names_normalized") or brain_event.get("rule_names_normalized"))
            rule_names_combined = []
            for r in (rule_names_local + rule_names_brain):
                if r not in rule_names_combined:
                    rule_names_combined.append(r)

            # risk_score: prefer annotated combined_risk_score on record, else look for global step_6 output list in globals
            combined_risk_score = coalesce(
                local_event.get("combined_risk_score"),
                brain_event.get("combined_risk_score"),
                rec_i.get("combined_risk_score")
            )
            if combined_risk_score is None:
                # try global numeric list from step_6 output (common names that may appear in globals)
                for name in ("step_6_output", "step6_output", "step_6", "step6", "combined_risk_scores"):
                    arr = g.get(name)
                    if isinstance(arr, list) and len(arr) >= num:
                        try:
                            val = arr[local_idx]
                            combined_risk_score = val if val is not None else 0
                            break
                        except Exception:
                            continue
            # final safe numeric coercion
            try:
                if combined_risk_score is None:
                    combined_risk_score = 0
                elif isinstance(combined_risk_score, bool):
                    combined_risk_score = int(combined_risk_score)
                elif isinstance(combined_risk_score, (int, float)):
                    combined_risk_score = int(round(combined_risk_score))
                elif isinstance(combined_risk_score, str):
                    combined_risk_score = int(round(float(combined_risk_score.strip())))
                else:
                    combined_risk_score = int(combined_risk_score)
            except Exception:
                combined_risk_score = 0

            # raw message summaries: prefer local_raw_summary/brain_raw_summary, else raw_summary, else build basic summary
            local_summary = coalesce(local_event.get("local_raw_summary"), local_event.get("raw_summary"))
            brain_summary = coalesce(brain_event.get("brain_raw_summary"), brain_event.get("raw_summary"))

            # If still None, attempt to build minimal summary from raw_message fields
            if local_summary is None:
                raw_local = local_event.get("raw_message", "")
                local_summary = {"sha256": None, "snippet": raw_local[:512] if isinstance(raw_local, str) else "", "length": len(raw_local) if isinstance(raw_local, str) else 0, "truncated": False}
            if brain_summary is None:
                raw_brain = brain_event.get("raw_message", "")
                brain_summary = {"sha256": None, "snippet": raw_brain[:512] if isinstance(raw_brain, str) else "", "length": len(raw_brain) if isinstance(raw_brain, str) else 0, "truncated": False}

            # Build the payload
            payload = {
                "alert_name": alert_name,
                "detection_source": detection_source,
                "severity": severity,
                "correlation_window": "15m",
                "timestamp_local": timestamp_local,
                "timestamp_brain": timestamp_brain,
                "host": host,
                "db_name": db_name,
                "target_account": target_account,
                "user": user_field,
                "action": action_field,
                "detectors": detectors_combined,
                "rule_names": rule_names_combined,
                "risk_score": combined_risk_score,
                "raw_messages": [
                    {"source": "local", "summary": deepcopy(local_summary)},
                    {"source": "brain", "summary": deepcopy(brain_summary)}
                ]
            }

            # Attach payload to both involved records (if writable)
            try:
                records[local_idx]["alert_payload"] = deepcopy(payload)
            except Exception:
                pass
            try:
                records[brain_idx]["alert_payload"] = deepcopy(payload)
            except Exception:
                pass

            # Append to global assembled_alerts (if available)
            try:
                assembled_alerts.append(deepcopy(payload))
            except Exception:
                pass

            # Mark both indices as True (payload assembled)
            results[local_idx] = True
            results[brain_idx] = True

        except Exception:
            # On unexpected errors for this index, leave results[i] as False and continue
            continue

    # Return boolean list aligned with input_list order indicating which entries had payloads assembled
    return results

def step_11(input_list):
    """
    Step 11: Construct a null-safe, sanitized, length-limited deduplication key and
    add it to the alert payload for suppression/deduplication.

    - Input: input_list (list of booleans, one per event; expected length 12)
    - Output: list of booleans (same length). Each True indicates that a dedup_key
      was successfully computed and attached to the alert_payload for that event (and its pair).
      If input_list[i] is False, result[i] will be False (not eligible).
    - Logic:
      * For each eligible index i (input_list[i] is True):
        - Find the corresponding record in a companion records list (from globals()).
        - Determine the local_event for the correlated pair (record where detected_by == "LOCAL"
          or detector == "LOCAL"). If the current record is not the local_event, search for
          the partner in the same identity group (host preferred, otherwise db_name+target_account).
        - Compute components (host_comp_safe, db_comp_safe, acct_comp_safe), preferring precomputed
          dedup_<field>_component keys when present. Each component:
            - coalesces to "-" when missing,
            - is trimmed, lowercased, and any sep characters replaced with "-",
            - is truncated to max_comp_len characters.
        - Compose dedup_key_safe = coalesce(local_event.dedup_key_precomp,
                                           host_comp_safe + sep + db_comp_safe + sep + acct_comp_safe)
        - Attach dedup_key_safe to the alert payload dict as alert_payload["dedup_key"] on both
          correlated records (create alert_payload if missing).
      * The function is defensive: handles missing globals, malformed records, and avoids raising.
    """
    # Parameters per step description
    sep = ":"
    max_comp_len = 128

    # Defensive: ensure input_list is a list
    if not isinstance(input_list, list):
        return []

    num = len(input_list)
    results = [False] * num

    # Attempt to find the companion records list in globals
    g = globals()
    possible_names = (
        "step_2_output", "step2_output", "processed_entries_step_2",
        "records", "step_2_data", "step_2"
    )
    records = None
    for name in possible_names:
        cand = g.get(name)
        if isinstance(cand, list) and len(cand) >= num and all(isinstance(x, dict) for x in cand[:num]):
            records = cand
            break

    # If no records list, can't proceed; return conservative result (same length).
    if records is None:
        return list(input_list)

    # Helper utilities
    def coalesce(*vals):
        for v in vals:
            if v is None:
                continue
            if isinstance(v, str) and v.strip() == "":
                continue
            return v
        return None

    def safe_trim_lower(val):
        try:
            if val is None:
                return None
            s = str(val).strip().lower()
            if s == "":
                return None
            return s
        except Exception:
            return None

    def replace_sep_and_truncate(text, separator, max_len):
        """
        Replace occurrences of separator with '-' in text and truncate to max_len.
        Returns a string (never None).
        """
        try:
            if text is None:
                text = "-"
            text = str(text)
            # trimmed lower outside when appropriate; this function expects pre-lower/trimming
            # but ensure there is no leading/trailing whitespace
            text = text.strip()
            if text == "":
                text = "-"
            # Replace the separator char/substring with '-'
            if separator and separator in text:
                text = text.replace(separator, "-")
            # Truncate
            if max_len is not None and isinstance(max_len, int) and max_len >= 0:
                text = text[:max_len]
            return text
        except Exception:
            # safe fallback
            return "-"

    # Helper to compute match key (used to find counterpart): host preferred, else db_name+target_account
    def match_key(entry):
        try:
            host = entry.get("host")
            if isinstance(host, str) and host.strip() != "":
                return ("host", host.strip().lower())
            db = entry.get("db_name")
            ta = entry.get("target_account")
            if isinstance(db, str) and db.strip() != "" and isinstance(ta, str) and ta.strip() != "":
                return ("db_target", (db.strip().lower(), ta.strip().lower()))
        except Exception:
            pass
        return (None, None)

    # Helper to determine if an entry is the local_event
    def is_local(entry):
        try:
            detected_by = entry.get("detected_by")
            detector = entry.get("detector")
            if isinstance(detected_by, str) and detected_by.strip().upper() == "LOCAL":
                return True
            if isinstance(detector, str) and detector.strip().upper() == "LOCAL":
                return True
            return False
        except Exception:
            return False

    # Precompute keys and roles for the batch to make counterpart lookup efficient
    keys = [ (None, None) ] * num
    local_flags = [ False ] * num
    for i in range(num):
        try:
            rec = records[i] if i < len(records) and isinstance(records[i], dict) else {}
            keys[i] = match_key(rec)
            local_flags[i] = is_local(rec)
        except Exception:
            keys[i] = (None, None)
            local_flags[i] = False

    # Iterate through the full list and process each eligible item
    for i in range(num):
        try:
            # Only process if eligible per input_list
            try:
                eligible = bool(input_list[i])
            except Exception:
                eligible = False
            if not eligible:
                results[i] = False
                continue

            # Ensure corresponding record exists and is a dict
            if i >= len(records) or not isinstance(records[i], dict):
                results[i] = False
                continue

            # Determine the correlated pair: find counterpart j with same match key and opposite role
            key_i = keys[i]
            if key_i[0] is None:
                # no usable identity grouping -> cannot reliably find pair/local event
                results[i] = False
                continue

            # Search for any counterpart j != i that is eligible and shares the same key
            counterpart_idx = None
            for j in range(num):
                if j == i:
                    continue
                if j >= len(records) or not isinstance(records[j], dict):
                    continue
                # counterpart must also be eligible per previous step
                try:
                    if not bool(input_list[j]):
                        continue
                except Exception:
                    continue
                if keys[j] != key_i:
                    continue
                # prefer counterpart that is opposite role (one local and one non-local). If neither is clearly brain/local, accept first eligible with same key.
                # We will prefer opposite roles: require at least one local in the pair.
                counterpart_idx = j
                # If we already have one that is opposite role, break early
                if local_flags[i] != local_flags[j]:
                    break

            if counterpart_idx is None:
                # No counterpart found -> cannot compute pair-level dedup key
                results[i] = False
                continue

            # Identify the local_event among the pair
            if local_flags[i]:
                local_idx = i
                other_idx = counterpart_idx
            elif local_flags[counterpart_idx]:
                local_idx = counterpart_idx
                other_idx = i
            else:
                # Neither side clearly marked LOCAL -> fall back to using current record as local_event
                # (this is conservative; better than skipping entirely)
                local_idx = i
                other_idx = counterpart_idx

            local_rec = records[local_idx]
            other_rec = records[other_idx]

            # Compute components with preference for precomputed component fields
            # host_comp_safe = coalesce(local_event.dedup_host_component,
            #                           substr(replace(trim(lower(coalesce(local_event.host, "-"))), sep, "-"), 0, max_comp_len))
            try:
                pre_host_comp = local_rec.get("dedup_host_component")
            except Exception:
                pre_host_comp = None
            if isinstance(pre_host_comp, str) and pre_host_comp.strip() != "":
                host_comp_safe = pre_host_comp.strip()
            else:
                raw_host = coalesce(local_rec.get("host"), "-")
                host_norm = safe_trim_lower(raw_host) or "-"  # ensures a non-empty string
                host_replaced = replace_sep_and_truncate(host_norm, sep, max_comp_len)
                host_comp_safe = host_replaced

            # db_comp_safe
            try:
                pre_db_comp = local_rec.get("dedup_db_component")
            except Exception:
                pre_db_comp = None
            if isinstance(pre_db_comp, str) and pre_db_comp.strip() != "":
                db_comp_safe = pre_db_comp.strip()
            else:
                raw_db = coalesce(local_rec.get("db_name"), "-")
                db_norm = safe_trim_lower(raw_db) or "-"
                db_replaced = replace_sep_and_truncate(db_norm, sep, max_comp_len)
                db_comp_safe = db_replaced

            # acct_comp_safe
            try:
                pre_acct_comp = local_rec.get("dedup_account_component")
            except Exception:
                pre_acct_comp = None
            if isinstance(pre_acct_comp, str) and pre_acct_comp.strip() != "":
                acct_comp_safe = pre_acct_comp.strip()
            else:
                raw_acct = coalesce(local_rec.get("target_account"), "-")
